-- Oct 2, 2026: Media and Content services (real estate, restaurants, and hidden drone/automotive items)
-- Run once in the Supabase SQL editor (paste the contents, not the file name). Safe to run again.
-- Hidden items (drone, automotive) are saved with website_visible=false and portal_visible=false.
-- To show them later: Admin > Service Catalog > open the item > turn on Website visible and Portal visible.
on conflict (id) do update set
  name=excluded.name, kind=excluded.kind, category=excluded.category, description=excluded.description,
  pricing_model=excluded.pricing_model, one_time_price=excluded.one_time_price, recurring_price=excluded.recurring_price,
  cadence=excluded.cadence, starting_at=excluded.starting_at, sales_mode=excluded.sales_mode,
  features=excluded.features, included=excluded.included, metadata=excluded.metadata, display_order=excluded.display_order, updated_at=now();
